      "de": "[dev-local-hub] Katalogveröffentlichung abgebrochen — /data/hub-dev behält seine bisherige Generation"
    },
    {
      "status": {
        "kind": "no-broker",
        "hubUrl": "http://127.0.0.1:7800",
        "dataDir": "/data/hub-dev"
      },
      "en": "[dev-local-hub] http://127.0.0.1:7800 has no session broker for /data/hub-dev — sign in through the shell",
      "de": "[dev-local-hub] http://127.0.0.1:7800 hat keinen Sitzungsvermittler für /data/hub-dev — melde dich in der Shell an"
    },
