          "kind": "ready",
          "url": "http://127.0.0.1:6540/",
          "waitedMs": 55200
        },
        "en": "[dev-serve] http://127.0.0.1:6540/ ready after 55 s",
        "de": "[dev-serve] http://127.0.0.1:6540/ bereit nach 55 s"
      },
      {
        "status": {
          "kind": "stopped",
          "url": "http://127.0.0.1:6540/"
        },
        "en": "[dev-serve] stopped http://127.0.0.1:6540/",
        "de": "[dev-serve] http://127.0.0.1:6540/ beendet"
