    ],
    "scenarios": [
      {
        "name": "a serve already answers: reused, and stop() leaves it running",
        "before": "http",
        "bootsAfterMs": null,
        "exits": false,
        "cancelAfterMs": null,
        "bootBoundMs": 5000,
        "expected": {
          "reused": true,
