        "exits": true,
        "cancelAfterMs": null,
        "bootBoundMs": 20000,
        "expected": {
          "reused": null,
          "statuses": [
            "spawning",
            "stopped"
          ],
          "error": "exited",
          "portFreeAfterStop": true
        }
