        "before": "tcp",
        "bootsAfterMs": null,
        "exits": false,
        "cancelAfterMs": null,
        "bootBoundMs": 5000,
        "expected": {
          "reused": null,
          "statuses": [],
          "error": "occupied",
          "portFreeAfterStop": false
